<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> classdef</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> OptogeneticStimulationParameter</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> dj.Lookup</span></span>
